Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
scsi: mpt3sas: Limit NVMe request size to 2 MiB

The HBA firmware reports NVMe MDTS values based on the underlying drive
capability. However, because the driver allocates a fixed 4K buffer for
the PRP list, accommodating at most 512 entries, the driver supports a
maximum I/O transfer size of 2 MiB.

Limit max_hw_sectors to the smaller of the reported MDTS and the 2 MiB
driver limit to prevent issuing oversized I/O that may lead to a kernel
oops.

Cc: stable@vger.kernel.org
Fixes: 9b8b84879d4a ("block: Increase BLK_DEF_MAX_SECTORS_CAP")
Reported-by: Mira Limbeck <m.limbeck@proxmox.com>
Closes: https://lore.kernel.org/r/291f78bf-4b4a-40dd-867d-053b36c564b3@proxmox.com
Link: https://git.kernel.org/pub/scm/linux/kernel/git/torvalds/linux.git/commit/?id=9b8b84879d4a
Suggested-by: Keith Busch <kbusch@kernel.org>
Signed-off-by: Ranjan Kumar <ranjan.kumar@broadcom.com>
Tested-by: Mira Limbeck <m.limbeck@proxmox.com>
Link: https://patch.msgid.link/20260414110811.85156-1-ranjan.kumar@broadcom.com
Signed-off-by: Martin K. Petersen <martin.petersen@oracle.com>

Here is the root cause:
The driver's `scsih_sdev_configure` function set `max_hw_sectors` solely based on the NVMe drive's MDTS value reported by firmware, without enforcing the driver's own hardware limitation from a fixed 4K PRP list buffer (max 512 entries, limiting I/O to 2 MiB). This allowed oversized I/O requests exceeding the driver's capability, leading to a kernel oops.

Here is the patch:
  */
 static int
 scsih_sdev_configure(struct scsi_device *sdev, struct queue_limits *lim)
 {
 	struct Scsi_Host *shost = sdev->host;
 	struct MPT3SAS_ADAPTER *ioc = shost_priv(shost);
 	struct MPT3SAS_DEVICE *sas_device_priv_data;
 	struct MPT3SAS_TARGET *sas_target_priv_data;
 	struct _sas_device *sas_device;
 	struct _pcie_device *pcie_device;
 	struct _raid_device *raid_device;
 	unsigned long flags;
 	int qdepth;
 	u8 ssp_target = 0;
 	char *ds = "";
 	char *r_level = "";
 	u16 handle, volume_handle = 0;
 	u64 volume_wwid = 0;
 	enum device_responsive_state retval;
 	u8 count = 0;

 	qdepth = 1;
 	sas_device_priv_data = sdev->hostdata;
 	sas_device_priv_data->configured_lun = 1;
 	sas_device_priv_data->flags &= ~MPT_DEVICE_FLAGS_INIT;
 	sas_target_priv_data = sas_device_priv_data->sas_target;
 	handle = sas_target_priv_data->handle;

 	/* raid volume handling */
 	if (sas_target_priv_data->flags & MPT_TARGET_FLAGS_VOLUME) {

 		spin_lock_irqsave(&ioc->raid_device_lock, flags);
 		raid_device = mpt3sas_raid_device_find_by_handle(ioc, handle);
 		spin_unlock_irqrestore(&ioc->raid_device_lock, flags);
 		if (!raid_device) {
 			dfailprintk(ioc,
 				    ioc_warn(ioc, "failure at %s:%d/%s()!\n",
 					     __FILE__, __LINE__, __func__));
 			return 1;
 		}

 		if (_scsih_get_volume_capabilities(ioc, raid_device)) {
 			dfailprintk(ioc,
 				    ioc_warn(ioc, "failure at %s:%d/%s()!\n",
 					     __FILE__, __LINE__, __func__));
 			return 1;
 		}

 		/*
 		 * WARPDRIVE: Initialize the required data for Direct IO
 		 */
 		mpt3sas_init_warpdrive_properties(ioc, raid_device);

 		/* RAID Queue Depth Support
 		 * IS volume = underlying qdepth of drive type, either
 		 *    MPT3SAS_SAS_QUEUE_DEPTH or MPT3SAS_SATA_QUEUE_DEPTH
 		 * IM/IME/R10 = 128 (MPT3SAS_RAID_QUEUE_DEPTH)
 		 */
 		if (raid_device->device_info &
 		    MPI2_SAS_DEVICE_INFO_SSP_TARGET) {
 			qdepth = MPT3SAS_SAS_QUEUE_DEPTH;
 			ds = "SSP";
 		} else {
 			qdepth = MPT3SAS_SATA_QUEUE_DEPTH;
 			if (raid_device->device_info &
 			    MPI2_SAS_DEVICE_INFO_SATA_DEVICE)
 				ds = "SATA";
 			else
 				ds = "STP";
 		}

 		switch (raid_device->volume_type) {
 		case MPI2_RAID_VOL_TYPE_RAID0:
 			r_level = "RAID0";
 			break;
 		case MPI2_RAID_VOL_TYPE_RAID1E:
 			qdepth = MPT3SAS_RAID_QUEUE_DEPTH;
 			if (ioc->manu_pg10.OEMIdentifier &&
 			    (le32_to_cpu(ioc->manu_pg10.GenericFlags0) &
 			    MFG10_GF0_R10_DISPLAY) &&
 			    !(raid_device->num_pds % 2))
 				r_level = "RAID10";
 			else
 				r_level = "RAID1E";
 			break;
 		case MPI2_RAID_VOL_TYPE_RAID1:
 			qdepth = MPT3SAS_RAID_QUEUE_DEPTH;
 			r_level = "RAID1";
 			break;
 		case MPI2_RAID_VOL_TYPE_RAID10:
 			qdepth = MPT3SAS_RAID_QUEUE_DEPTH;
 			r_level = "RAID10";
 			break;
 		case MPI2_RAID_VOL_TYPE_UNKNOWN:
 		default:
 			qdepth = MPT3SAS_RAID_QUEUE_DEPTH;
 			r_level = "RAIDX";
 			break;
 		}

 		if (!ioc->hide_ir_msg)
 			sdev_printk(KERN_INFO, sdev,
 			   "%s: handle(0x%04x), wwid(0x%016llx),"
 			    " pd_count(%d), type(%s)\n",
 			    r_level, raid_device->handle,
 			    (unsigned long long)raid_device->wwid,
 			    raid_device->num_pds, ds);

 		if (shost->max_sectors > MPT3SAS_RAID_MAX_SECTORS) {
 			lim->max_hw_sectors = MPT3SAS_RAID_MAX_SECTORS;
 			sdev_printk(KERN_INFO, sdev,
 					"Set queue's max_sector to: %u\n",
 						MPT3SAS_RAID_MAX_SECTORS);
 		}

 		mpt3sas_scsih_change_queue_depth(sdev, qdepth);

 		/* raid transport support */
 		if (!ioc->is_warpdrive)
 			_scsih_set_level(ioc, sdev, raid_device->volume_type);
 		return 0;
 	}

 	/* non-raid handling */
 	if (sas_target_priv_data->flags & MPT_TARGET_FLAGS_RAID_COMPONENT) {
 		if (mpt3sas_config_get_volume_handle(ioc, handle,
 		    &volume_handle)) {
 			dfailprintk(ioc,
 				    ioc_warn(ioc, "failure at %s:%d/%s()!\n",
 					     __FILE__, __LINE__, __func__));
 			return 1;
 		}
 		if (volume_handle && mpt3sas_config_get_volume_wwid(ioc,
 		    volume_handle, &volume_wwid)) {
 			dfailprintk(ioc,
 				    ioc_warn(ioc, "failure at %s:%d/%s()!\n",
 					     __FILE__, __LINE__, __func__));
 			return 1;
 		}
 	}

 	/* PCIe handling */
 	if (sas_target_priv_data->flags & MPT_TARGET_FLAGS_PCIE_DEVICE) {
 		spin_lock_irqsave(&ioc->pcie_device_lock, flags);
 		pcie_device = __mpt3sas_get_pdev_by_wwid(ioc,
 				sas_device_priv_data->sas_target->sas_address);
 		if (!pcie_device) {
 			spin_unlock_irqrestore(&ioc->pcie_device_lock, flags);
 			dfailprintk(ioc,
 				    ioc_warn(ioc, "failure at %s:%d/%s()!\n",
 					     __FILE__, __LINE__, __func__));
 			return 1;
 		}

 		qdepth = ioc->max_nvme_qd;
 		ds = "NVMe";
 		sdev_printk(KERN_INFO, sdev,
 			"%s: handle(0x%04x), wwid(0x%016llx), port(%d)\n",
 			ds, handle, (unsigned long long)pcie_device->wwid,
 			pcie_device->port_num);
 		if (pcie_device->enclosure_handle != 0)
 			sdev_printk(KERN_INFO, sdev,
 			"%s: enclosure logical id(0x%016llx), slot(%d)\n",
 			ds,
 			(unsigned long long)pcie_device->enclosure_logical_id,
 			pcie_device->slot);
 		if (pcie_device->connector_name[0] != '\0')
 			sdev_printk(KERN_INFO, sdev,
 				"%s: enclosure level(0x%04x),"
 				"connector name( %s)\n", ds,
 				pcie_device->enclosure_level,
 				pcie_device->connector_name);

+		/*
+		 * The HBA firmware passes the NVMe drive's MDTS
+		 * (Maximum Data Transfer Size) up to the driver. However,
+		 * the driver hardcodes a 4K buffer size for the PRP list,
+		 * accommodating at most 512 entries. This strictly limits
+		 * the maximum supported NVMe I/O transfer to 2 MiB.
+		 *
+		 * Cap max_hw_sectors to the smaller of the drive's reported
+		 * MDTS or the 2 MiB driver limit to prevent kernel oopses.
+		 */
+		lim->max_hw_sectors = SZ_2M >> SECTOR_SHIFT;
 		if (pcie_device->nvme_mdts)
-			lim->max_hw_sectors = pcie_device->nvme_mdts / 512;
+			lim->max_hw_sectors = min(lim->max_hw_sectors,
+					pcie_device->nvme_mdts >> SECTOR_SHIFT);

 		pcie_device_put(pcie_device);
 		spin_unlock_irqrestore(&ioc->pcie_device_lock, flags);

 		mpt3sas_scsih_change_queue_depth(sdev, qdepth);
 		lim->virt_boundary_mask = ioc->page_size - 1;
 		return 0;
 	}

 	spin_lock_irqsave(&ioc->sas_device_lock, flags);
 	sas_device = __mpt3sas_get_sdev_by_addr(ioc,
 	   sas_device_priv_data->sas_target->sas_address,
 	   sas_device_priv_data->sas_target->port);
 	if (!sas_device) {
 		spin_unlock_irqrestore(&ioc->sas_device_lock, flags);
 		dfailprintk(ioc,
 			    ioc_warn(ioc, "failure at %s:%d/%s()!\n",
 				     __FILE__, __LINE__, __func__));
 		return 1;
 	}

 	sas_device->volume_handle = volume_handle;
 	sas_device->volume_wwid = volume_wwid;
 	if (sas_device->device_info & MPI2_SAS_DEVICE_INFO_SSP_TARGET) {
 		qdepth = (sas_device->port_type > 1) ?
 			ioc->max_wideport_qd : ioc->max_narrowport_qd;
 		ssp_target = 1;
 		if (sas_device->device_info &
 				MPI2_SAS_DEVICE_INFO_SEP) {
 			sdev_printk(KERN_INFO, sdev,
 			"set ignore_delay_remove for handle(0x%04x)\n",
 			sas_device_priv_data->sas_target->handle);
 			sas_device_priv_data->ignore_delay_remove = 1;
 			ds = "SES";
 		} else
 			ds = "SSP";
 	} else {
 		qdepth = ioc->max_sata_qd;
 		if (sas_device->device_info & MPI2_SAS_DEVICE_INFO_STP_TARGET)
 			ds = "STP";
 		else if (sas_device->device_info &
 		    MPI2_SAS_DEVICE_INFO_SATA_DEVICE)
 			ds = "SATA";
 	}

 	sdev_printk(KERN_INFO, sdev, "%s: handle(0x%04x), " \
 	    "sas_addr(0x%016llx), phy(%d), device_name(0x%016llx)\n",
 	    ds, handle, (unsigned long long)sas_device->sas_address,
 	    sas_device->phy, (unsigned long long)sas_device->device_name);

 	_scsih_display_enclosure_chassis_info(NULL, sas_device, sdev, NULL);

 	sas_device_put(sas_device);
 	spin_unlock_irqrestore(&ioc->sas_device_lock, flags);

 	if (!ssp_target) {
 		_scsih_display_sata_capabilities(ioc, handle, sdev);

 		do {
 			retval = _scsih_ata_pass_thru_idd(ioc, handle,
 				    &sas_device->ssd_device, 30, 0);
 		} while ((retval == DEVICE_RETRY || retval == DEVICE_RETRY_UA)
 			&& count++ < 3);
 	}


 	mpt3sas_scsih_change_queue_depth(sdev, qdepth);

 	if (ssp_target) {
 		sas_read_port_mode_page(sdev);
 		_scsih_enable_tlr(ioc, sdev);
 	}

 	return 0;
 }



